public class OFDIntegrityTest {

    @Test
    public void testProtectIntegrity() throws Exception {
        // Setup Bouncy Castle security provider
        Security.addProvider(new BouncyCastleProvider());

        // Define paths for input and output
        Path workDir = Paths.get("src/test/resources/input");
        Path destDir = Paths.get("src/test/resources/output");

        // Ensure the destination directory exists
        if (!Files.exists(destDir)) {
            Files.createDirectories(destDir);
        }

        // Define the OFD file path
        Path ofdFile = workDir.resolve("hello.ofd");

        // Ensure the OFD file exists
        if (!Files.exists(ofdFile)) {
            Files.createFile(ofdFile);
        }

        // Initialize OFDIntegrity with input OFD file and destination directory
        OFDIntegrity integrity = new OFDIntegrity(ofdFile, destDir);

        try {
            // Load certificate
            CertificateFactory certFactory = CertificateFactory.getInstance("X.509");
            X509Certificate certificate;
            try (FileInputStream certInput = new FileInputStream(workDir.resolve("sign_cert.pem").toFile())) {
                certificate = (X509Certificate) certFactory.generateCertificate(certInput);
            }

            // Load private key
            Path keyPath = workDir.resolve("sign_key.pem");
            byte[] keyBytes = Files.readAllBytes(keyPath);
            PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(keyBytes);
            KeyFactory keyFactory = KeyFactory.getInstance("RSA"); // Replace "RSA" with the appropriate algorithm if different
            PrivateKey privateKey = keyFactory.generatePrivate(keySpec);

            // Initialize ProtectSigner with private key and certificate
            ProtectSigner signer = new GMProtectSigner(privateKey, certificate);

            // Execute the protect method
            integrity.protect(signer);

            // Define the expected signed OFD file path
            Path signedOFD = destDir.resolve("hello-integrity.ofd");

            // Assert that the signed OFD file exists
            assertTrue(Files.exists(signedOFD), "Signed OFD file should be created successfully");

        } finally {
            // Clean up resources
            integrity.close();
        }
    }
}

