import org.ofdrw.pkg.container.PageDir;
import org.ofdrw.core.basicStructure.pageObj.Page;

class OFDPageGraphics2DTest {

    @Test
    void testTransformAppliesCorrectly() throws Exception {
        // Preconditions
        // Assume 'target/' directory exists
        // Assume document and graphics context are initialized
        // Graphics context starts with identity transform

        // Initialize necessary parameters
        // Use reflection to access the private constructor of a generic GraphicsDocument
        Constructor<?> constructor = Class.forName("org.ofdrw.graphics2d.GraphicsDocument").getDeclaredConstructor();
        constructor.setAccessible(true);
        Object doc = constructor.newInstance();

        ST_ID pageID = new ST_ID("page1");
        PageDir pageDir = new PageDir(Paths.get("target/"));
        Page pageObj = new Page();
        Rectangle2D.Double box = new Rectangle2D.Double(0, 0, 800, 600);

        // Create graphics context with required parameters
        OFDPageGraphics2D graphics = new OFDPageGraphics2D(doc, pageID, pageDir, pageObj, box);

        // Define the affine transformation to apply
        AffineTransform tx = new AffineTransform();
        tx.scale(0.83, 0.83);
        tx.shear(-0.58, 0.83);
        tx.translate(127.45, 127.45);

        // Apply the transformation
        graphics.transform(tx);

        // Expected transformation matrix components
        double expectedScaleX = 0.83;
        double expectedShearY = -0.58;
        double expectedShearX = 0.83;
        double expectedScaleY = 0.83;
        double expectedTranslateX = 127.45;
        double expectedTranslateY = 127.45;

        // Retrieve the current transformation matrix
        AffineTransform currentTransform = graphics.getTransform();
        double[] matrix = new double[6];
        currentTransform.getMatrix(matrix);

        // Assertions
        assertEquals(expectedScaleX, matrix[0], 0.001, "Scale X mismatch");
        assertEquals(expectedShearY, matrix[1], 0.001, "Shear Y mismatch");
        assertEquals(expectedShearX, matrix[2], 0.001, "Shear X mismatch");
        assertEquals(expectedScaleY, matrix[3], 0.001, "Scale Y mismatch");
        assertEquals(expectedTranslateX, matrix[4], 0.001, "Translate X mismatch");
        assertEquals(expectedTranslateY, matrix[5], 0.001, "Translate Y mismatch");
    }

}

