class OFDPageGraphics2DTest {

    @Test
    void setTransform_SetAndResetCTM() throws Exception {
        // Define the output path
        final Path dst = Paths.get("target/complexCTMSetAndReset.ofd");

        // Ensure the target directory exists
        Files.createDirectories(dst.getParent());

        // Create the OFD graphics document
        try (OFDGraphicsDocument doc = new OFDGraphicsDocument(dst)) {
            // Initialize the graphics context with a 500x500 page
            OFDPageGraphics2D g = doc.newPage(500, 500);

            // Apply rotation (45 degrees) and translation (100, 100)
            AffineTransform initialTransform = new AffineTransform();
            initialTransform.rotate(Math.toRadians(45), 250, 250);
            initialTransform.translate(100, 100);
            g.setTransform(initialTransform);

            // Set color to red and draw a rectangle
            g.setColor(Color.RED);
            g.fillRect(150, 150, 200, 200);

            // Reset the transformation matrix
            g.setTransform(new AffineTransform());

            // Apply translation (50, 50) and rotation (30 degrees)
            AffineTransform resetTransform = new AffineTransform();
            resetTransform.translate(50, 50);
            resetTransform.rotate(Math.toRadians(30), 250, 250);
            g.setTransform(resetTransform);

            // Set color to blue and draw another rectangle
            g.setColor(Color.BLUE);
            g.fillRect(100, 100, 300, 300);

            // Dispose the graphics context
            g.dispose();
        }

        // Assert that the output file has been created successfully
        assertTrue(Files.exists(dst), "The output OFD file should be generated successfully.");
    }

}

