    @Test
    void setClip_CropAndRotateImage() throws Exception {
        // Enable debugging output
        // DebugTool.ENABLE_DEBUG_PRINT = true; // Removed debug tool

        // Define paths
        Path sourceImagePath = Paths.get("src/test/resources/sourceImage.png");
        Path destinationPath = Paths.get("target/outputGraphics.pdf");

        // Load source image
        BufferedImage sourceImage = ImageIO.read(sourceImagePath.toFile());

        // Create document
        try (GraphicsDocument doc = new GraphicsDocument(destinationPath)) {
            PageGraphics2D g = doc.newPage(500, 500);

            // Set clip to crop the image
            g.setClip(100, 100, 100, 100);

            // Draw the cropped image
            g.drawImage(sourceImage, 100, 100, null);

            // Apply rotation
            AffineTransform rotateTransform = AffineTransform.getRotateInstance(Math.toRadians(10), 150, 150);
            g.transform(rotateTransform);

            // Draw the rotated image
            g.drawImage(sourceImage, 100, 100, null);

            // Dispose graphics
            g.dispose();
        }

        // Assert the output file is created
        assertTrue(destinationPath.toFile().exists(), "Output PDF file should be created.");

        System.out.println("Output file created at: " + destinationPath.toAbsolutePath());
    }

}

