        }

<COVER>        double x = 0;
<COVER>        switch (this.textAlign) {

            case right:
            case end:
                // 右浮动
                x = canvas.getWidth() - img.width;
                break;
            case center:
                // 居中
<COVER>                x = (canvas.getWidth() - img.width) / 2d;
<COVER>                break;
            case start:
            case left:
            default:
                // 左浮动
                x = 0d;
                break;
        }
<COVER>        double y = 0;
<COVER>        switch (this.verticalAlign) {
            case bottom:
                y = canvas.getHeight() - img.height;
