            case center:
<COVER>                y = (canvas.getHeight() - img.height) / 2d;
<COVER>                break;
            case top:
            default:
                y = 0d;
                break;
        }
<COVER>        ctx.drawImage(img.path, x, y, img.width, img.height);

<COVER>        if (DEBUG) {
